/**
 * The seat count every plan check compares against.
 * A suspended member keeps their seat; only removal (archive) frees it.
 */
export async function countActiveMembers(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        or(eq(members.status, "active"), eq(members.status, "suspended")),
        liveMemberPredicate(),
      ),
    )
    .get();
  return row?.value ?? 0;
}

/** Suspension and reinstatement. Removal stays an archive, not a status flip. */
export async function setMemberStatus(
  orgId: OrgId,
  memberId: MemberId,
  status: Extract<MemberStatus, "active" | "suspended">,
): Promise<Member> {
  const row = getDb()
    .update(members)
    .set({ status, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.id, memberId),
        liveMemberPredicate(),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  return toMember(row);
}

